(out/'styles.css').write_text(css,encoding='utf-8')
repo='https://github.com/esst-prog2/RC_ATLAS_Project'
setup=repo+'/blob/main/docs/DEVELOPMENT.md'
arrow='<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M5 12h14M13 6l6 6-6 6"/></svg>'
mark='<svg class="mark" aria-hidden="true" viewBox="0 0 36 36"><rect width="36" height="36" rx="7" fill="#11828a"/><path d="M9 26V10h5v11h13v5z" fill="white"/></svg>'
names=['Evidence-led editorial','Institutional overview','Accountability journey']
slugs=['editorial','overview','journey']
capabilities=[('Project management','Organize project work, assign responsibility, set deadlines, and follow tasks through review.',''),('Monitoring','Follow operational progress and reporting records. See what has been submitted and what still needs attention.',''),('Indicators','Examine baselines, targets, and results. For configured indicators, inspect the selected method and reporting period.','Indicator analysis requires approved methods and suitable source data.'),('Analytics','Understand supported indicator calculations through explanations, source context, and data-quality checks.','Checks apply to the selected indicator. Missing configuration and unsupported results are identified explicitly.'),('Reporting','Review recorded information and prepare report previews for discussion and decisions.','Fully governed report and export snapshots remain future work.')]
steps=[('Assign','Programme manager','Set responsibility and a deadline.'),('Work','Field coordinator','Start the task and update progress.'),('Submit','Field coordinator','Send completed work for review.'),('Validate','Reviewer','Examine the submission.'),('Approve','Programme manager','Confirm the final completion checkpoint.')]

def actions(slug,light=False):
 return f'<div class="actions"><a class="button {"light" if light else ""}" href="{repo}">Explore on GitHub {arrow}</a><a class="text-link" href="#{slug}-workflow">See the workflow</a></div>'
def title():
 return '<h1 class="hero-title"><span class="sr">RC Atlas — </span>From institutional data<br class="wide-break"> to <em>coordinated action.</em></h1>'
def header(slug,n):
 return f'''<a class="skip" href="#{slug}-start">Skip to content</a><div class="review-strip"><div class="wrap"><span>{names[n]} · Design preview</span><a href="index.html">Compare all three</a></div></div><header><div class="wrap"><a class="brand" href="#{slug}-start">{mark}RC Atlas</a><nav aria-label="Main navigation"><a href="#{slug}-capabilities">Capabilities</a><a href="#{slug}-workflow">The workflow</a><a href="#{slug}-explore">Explore</a></nav></div></header>'''
def caps(slug):
 items=''.join(f'<div class="cap-item" id="{slug}-cap-{i}"><h3>{name}</h3><div><p>{desc}</p>{f"<small>{limit}</small>" if limit else ""}</div></div>' for i,(name,desc,limit) in enumerate(capabilities))
 heading='<h2>One workspace.<br>Five connected capabilities.</h2>'
 intro='<p>For programme managers, field coordinators, and monitoring and evaluation teams. Bring responsibilities, reporting information, and indicator evidence into a clearer view.</p>'
 if slug=='journey':
  return f'<section class="section capabilities" id="{slug}-capabilities"><div class="wrap"><div class="cap-body"><div class="cap-intro">{heading}<div style="margin-top:24px">{intro}</div></div><div class="cap-list">{items}</div></div></div></section>'
 return f'<section class="section capabilities" id="{slug}-capabilities"><div class="wrap"><div class="section-heading">{heading}{intro}</div><div class="cap-list">{items}</div></div></section>'
def workflow(slug):
 items=''.join(f'<li class="step"><span class="order">{i+1:02d}</span><h3>{name}</h3><p><strong>{role}</strong><br>{desc}</p></li>' for i,(name,role,desc) in enumerate(steps))
 return f'''<section class="section workflow" id="{slug}-workflow"><div class="wrap"><div class="section-heading"><h2>Accountability,<br>one handoff at a time.</h2><p>Follow one task from assignment to approval. Each handoff makes responsibility clear and gives the next person a defined part in the review.</p></div><ol class="steps" aria-label="Illustrated assignment-to-approval workflow">{items}</ol><p class="note">Workflow illustration, not an application screenshot. This example uses both validation and approval; other configured task flows exist.</p></div></section>'''
def understand(slug):
 return f'''<section class="section understand" id="{slug}-evidence"><div class="wrap"><div class="section-heading"><h2>Know what the result<br>can tell you.</h2><p>Institutional decisions need more than a completed-task count. Delivery checks and indicator evidence answer different questions.</p></div><div class="facts"><article><h3>Work completed.</h3><p>A completed task shows that the work passed its delivery checks. Responsibilities, deadlines, progress, and review checkpoints describe what happened.</p></article><article><h3>Results understood.</h3><p>Configured indicators offer a separate view of what the data shows. Examine the method, period, source context, and limitations before interpreting a result.</p><ul><li>Keep task progress distinct from measured outcomes.</li><li>Recognize when a calculation is unavailable.</li><li>Use reporting records and previews to support review.</li></ul></article></div></div></section>'''
def explore(slug):
 return f'''<section class="section explore" id="{slug}-explore"><div class="wrap"><div class="explore-grid"><div><h2>Explore the work.<br>Understand the approach.</h2><p class="lead">RC Atlas is a locally run course project. The public repository contains the source, the practical workflow, and instructions for running the application.</p><a class="button" href="{repo}">Explore on GitHub {arrow}</a></div><aside class="local-guide" aria-label="Explore locally"><h3>Start with the workflow.</h3><p>Read the documented example, then use the setup guide to explore RC Atlas on your own computer. A fresh installation needs local initialization.</p><a class="text-link" href="{setup}">Read the local setup guide</a></aside></div><div class="scope"><strong>Current scope</strong><p>Indicator analysis requires configured methods and suitable data. Some wider analytical and reporting functions remain under development. This website does not host the application or offer a production service.</p></div></div></section><footer><div class="wrap"><span>RC Atlas · From institutional data to coordinated action.</span><a href="{repo}">View the project on GitHub</a></div></footer>'''
def hero(slug):
 if slug=='editorial':
  return f'''<section class="hero" id="{slug}-start"><div class="wrap">{title()}<div class="editorial-intro"><p class="lead">Bring project work, monitoring information, and indicator evidence into one institutional workspace.</p>{actions(slug)}</div><div class="editorial-evidence"><div class="statement"><h2>Work you can trace.<br>Evidence you can explain.</h2><p>A clearer picture of responsibilities, results, and the review behind each decision.</p></div><div class="proof-box"><div class="diagram-title">Two complementary views of accountability</div><div class="proof-row"><strong>Delivery</strong><span>Who owns the work?<br>What is due? What has been reviewed?</span></div><div class="proof-row"><strong>Evidence</strong><span>What does the indicator measure?<br>Which method, source, and period?</span></div><p class="diagram-caption">Conceptual explanation · not an application screenshot</p></div></div><div class="audience-line"><strong>Built around institutional work.</strong><span>Project teams · Field coordination · Monitoring &amp; evaluation</span></div></div></section>'''
 if slug=='overview':
  directory=''.join(f'<a href="#{slug}-cap-{i}">{name}<span>{sub}</span></a>' for i,(name,sub) in enumerate([('Project management','Responsibility & delivery'),('Monitoring','Progress & records'),('Indicators','Baselines & targets'),('Analytics','Methods & evidence'),('Reporting','Review & discussion')]))
  return f'''<section class="hero" id="{slug}-start"><div class="wrap">{title()}<div class="hero-summary"><p class="lead">Project work, monitoring, indicators, analytics, and reporting. A connected workspace for teams that need to understand both delivery and results.</p>{actions(slug,True)}</div><nav class="cap-directory" aria-label="Explore the five capabilities">{directory}</nav></div></section>'''
 return f'''<section class="hero" id="{slug}-start"><div class="wrap"><div class="hero-opening">{title()}<div><p class="lead">Connect institutional information to responsibilities, review, and decisions. Follow the work. Understand the evidence.</p>{actions(slug)}</div></div><div class="route-map" aria-label="Conceptual information-to-action journey"><article class="route-stop"><h2>Make it visible.</h2><p>Bring project work, reporting records, and indicators into view.</p><a href="#{slug}-capabilities">Explore the capabilities</a></article><article class="route-stop"><h2>Make it accountable.</h2><p>Give people clear responsibilities and defined review checkpoints.</p><a href="#{slug}-workflow">Follow the handoffs</a></article><article class="route-stop"><h2>Make it understood.</h2><p>Examine results and limitations before drawing conclusions.</p><a href="#{slug}-evidence">Understand the evidence</a></article></div><p class="diagram-caption">Conceptual journey · not an application screenshot</p></div></section>'''
contents=[]
for n,slug in enumerate(slugs):
 body=f'<main class="site {slug}">'+header(slug,n)+hero(slug)+caps(slug)+workflow(slug)+understand(slug)+explore(slug)+'</main>'
 contents.append(body)
 doc=f'<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="RC Atlas promotional design preview: {names[n]}."><title>{names[n]} — RC Atlas</title><link rel="icon" href="data:,"><link rel="stylesheet" href="styles.css"><style>html{{scrollbar-color:#11828a #e8eef5}}body{{margin:0}}</style></head><body>{body}</body></html>'
 (out/f'{slug}.html').write_text(doc,encoding='utf-8')
print('Generated three standalone promotional previews. No variant selected.')
